// PPTX 导出模块
// PptxGenJS (本地文件加载)

// 加载 PptxGenJS 库
function loadPptxGenJS() {
    return new Promise(function(resolve, reject) {
        if (window.PptxGenJS) {
            resolve(window.PptxGenJS);
            return;
        }
        var script = document.createElement('script');
        script.src = chrome.runtime.getURL('bundles/pptxgen.bundle.min.js');
        script.onload = function() { resolve(window.PptxGenJS); };
        script.onerror = function() { reject(new Error('PPT库加载失败')); };
        document.head.appendChild(script);
    });
}

// 导出为 PPT
async function exportToPPT(steps) {
    try {
        console.log('[PPT] Starting export, steps:', steps.length);
        
        var PptxGenJS = await loadPptxGenJS();
        var pptx = new PptxGenJS();
        pptx.author = 'SnapScribe';
        pptx.company = 'SnapScribe';
        
        // 标题页
        var titleSlide = pptx.addSlide();
        titleSlide.addText('操作步骤文档', {
            x: 1, y: 2.5, w: 8.5, h: 1,
            fontSize: 40, bold: true, color: 'FFFFFF', align: 'center'
        });
        
        var dateStr = new Date().toLocaleString('zh-CN');
        titleSlide.addText('生成时间: ' + dateStr, {
            x: 1, y: 3.8, w: 8.5, h: 0.5,
            fontSize: 16, color: 'FFFFFF', align: 'center'
        });
        
        titleSlide.addText('总步骤数: ' + steps.length, {
            x: 1, y: 4.4, w: 8.5, h: 0.5,
            fontSize: 16, color: 'FFFFFF', align: 'center'
        });
        
        // 步骤幻灯片
        for (var i = 0; i < steps.length; i++) {
            var step = steps[i] || {};
            var slide = pptx.addSlide();
            
            // 标题
            var titleText = step.title ? String(step.title) : ('步骤 ' + (i + 1));
            slide.addText(titleText, {
                x: 0.5, y: 0.3, w: 9, h: 0.6,
                fontSize: 24, bold: true, color: '2c3e50'
            });
            
            // 添加图片
            if (step.screenshot && typeof step.screenshot === 'string' && step.screenshot.indexOf('data:') === 0) {
                try {
                    slide.addImage({
                        data: step.screenshot,
                        x: 0.5, y: 1.2, w: 9, h: 5
                    });
                } catch (imgErr) {
                    console.error('[PPT] Image error:', imgErr);
                    slide.addText('[图片加载失败]', {
                        x: 0.5, y: 3, w: 9, h: 0.5,
                        fontSize: 14, color: '999999', align: 'center'
                    });
                }
            }
            
            // 时间戳
            if (step.timestamp) {
                try {
                    var timeText = new Date(step.timestamp).toLocaleString('zh-CN');
                    if (timeText && timeText !== 'Invalid Date') {
                        slide.addText(timeText, {
                            x: 0.5, y: 6.3, w: 9, h: 0.3,
                            fontSize: 10, color: '7f8c8d'
                        });
                    }
                } catch (e) {}
            }
        }
        
        // 生成文件
        var blob = await pptx.write({ type: 'blob' });
        
        var now = new Date();
        var filename = 'SnapScribe操作步骤_' + 
            now.getFullYear() + 
            String(now.getMonth() + 1).padStart(2, '0') + 
            String(now.getDate()).padStart(2, '0') + '_' +
            String(now.getHours()).padStart(2, '0') + 
            String(now.getMinutes()).padStart(2, '0') + '.pptx';
        
        var reader = new FileReader();
        return new Promise(function(resolve, reject) {
            reader.onload = function() {
                chrome.runtime.sendMessage({
                    action: 'downloadFile',
                    data: { dataUrl: reader.result, filename: filename }
                }, function() {
                    resolve({ success: true, filename: filename });
                });
            };
            reader.onerror = function() { reject(new Error('文件转换失败')); };
            reader.readAsDataURL(blob);
        });
        
    } catch (error) {
        console.error('[PPT] Export error:', error);
        throw error;
    }
}

// 导出为 PPTX 文件
async function handlePPTExport() {
    var stepsCopy = steps.slice(); // 浅拷贝
    await exportToPPT(stepsCopy);
}
